def NS = 'urn:sciback:midpoint:person'
def HOY = java.time.LocalDate.now(java.time.ZoneId.of('America/Lima'))
def fecha = { v -> def s = (v == null) ? '' : basic.stringify(v).trim(); (s ==~ /\d{4}-\d{2}-\d{2}.*/) ? java.time.LocalDate.parse(s.substring(0, 10)) : null }
// G1: fin real de la matricula CON MEMORIA. terminationDateStudent (IIA e22) puede BAJAR cuando un
// semestre sale del horizonte del feed (medido 29-oct: 21 de los 46). Regla:
//   sube o igual -> se acepta; baja con el fin previo YA pasado -> memoria (fin de modulo, no retiro);
//   baja ANTES del fin previsto -> retiro/anulacion (cursos ESTADO=3) -> se acepta el valor menor.
def t = fecha(terminationDateStudent)
def prev = fecha(basic.getExtensionPropertyValue(focus, NS, 'studentEnrollmentLastEnd'))
if (t == null) return prev?.toString()
if (prev == null || !t.isBefore(prev)) return t.toString()
if (HOY.isBefore(prev)) return t.toString()
return prev.toString()

// N = DIAS DE GRACIA tras el fin real de la matricula. UNICO SITIO donde vive N.
// Cambiarlo = PATCH replace de este <code> (item mapping[5849]) y recompute de los afectados.
def N = 90
def s = (studentEnrollmentLastEnd == null) ? '' : basic.stringify(studentEnrollmentLastEnd).trim()
if (!(s ==~ /\d{4}-\d{2}-\d{2}.*/)) return null
def fin = java.time.LocalDate.parse(s.substring(0, 10))
// Alumno + personal/egresado: la gracia NO aplica (su estado lo sostiene 216/215; no cambian).
def otro = [worker, alum].any { it != null && basic.stringify(it).trim() != '' }
return (otro ? fin : fin.plusDays(N)).toString()

def NS = 'urn:sciback:midpoint:person'
def HOY = java.time.LocalDate.now(java.time.ZoneId.of('America/Lima'))
def fecha = { v -> def s = (v == null) ? '' : basic.stringify(v).trim(); (s ==~ /\d{4}-\d{2}-\d{2}.*/) ? java.time.LocalDate.parse(s.substring(0, 10)) : null }
if (input == null || basic.stringify(input).trim() == '') return false
def vivo
try { vivo = midpoint.hasLinkedAccount('6a91f7e1-1b50-4dcf-9c4b-7c0c0e0e0e22') } catch (Exception e) { log.warn('R1v3: hasLinkedAccount fallo en {}: {} -> no se retira', focus?.name, e.message); return false }
if (vivo) return false
def fin = fecha(basic.getExtensionPropertyValue(focus, NS, 'studentEnrollmentLastEnd'))
def eff = fecha(basic.getExtensionPropertyValue(focus, NS, 'studentEnrollmentEffectiveEnd'))
def enGracia = fin != null && eff != null && !HOY.isBefore(fin) && !HOY.isAfter(eff)
if (enGracia) return false
log.warn('R1v3: retira {} de {} (sin cuenta e22 viva y fuera de la gracia: fin={} eff={})', input, focus?.name, fin, eff)
return true

import com.evolveum.midpoint.xml.ns._public.common.common_3.TriggerType
import com.evolveum.midpoint.prism.xml.XmlTypeConverter
def NS = 'urn:sciback:midpoint:person'
def HOY = java.time.LocalDate.now(java.time.ZoneId.of('America/Lima'))
def fecha = { v -> def s = (v == null) ? '' : basic.stringify(v).trim(); (s ==~ /\d{4}-\d{2}-\d{2}.*/) ? java.time.LocalDate.parse(s.substring(0, 10)) : null }
def out = []
def s217 = basic.getExtensionPropertyValue(focus, NS, 'liveAffiliationStudent')
if (s217 == null || basic.stringify(s217).trim() == '') return out
def vivo
try { vivo = midpoint.hasLinkedAccount('6a91f7e1-1b50-4dcf-9c4b-7c0c0e0e0e22') } catch (Exception e) { return out }
if (vivo) return out
def fin = fecha(basic.getExtensionPropertyValue(focus, NS, 'studentEnrollmentLastEnd'))
def eff = fecha(basic.getExtensionPropertyValue(focus, NS, 'studentEnrollmentEffectiveEnd'))
def enGracia = fin != null && eff != null && !HOY.isBefore(fin) && !HOY.isAfter(eff)
if (!enGracia) return out
// Solo fechas ESTRICTAMENTE futuras (mismo guardarrail que N2: sin bucle al disparar).
def d = eff.plusDays(1)
if (!d.isAfter(HOY)) return out
def ZONE = java.time.ZoneId.of('America/Lima')
def t = new TriggerType()
t.setHandlerUri('http://midpoint.evolveum.com/xml/ns/public/model/trigger/recompute/handler-3')
t.setTimestamp(XmlTypeConverter.createXMLGregorianCalendar(d.atStartOfDay(ZONE).toInstant().toEpochMilli()))
out.add(t)
return out
